// let 默认不可变，歌名绑定后不可重新赋值
let song_title = "Snow Halo";
println!("{}", song_title);

// mut 允许后续重新赋值，如累计播放次数
let mut play_count = 0;
play_count += 1;
println!("{}", play_count);

// 冒号后写类型，数字字面量可用下划线分组
let volume: f32 = 0.85;
let fans: u64 = 1_000_000;
println!("{} {}", volume, fans);

// 新绑定遮蔽旧绑定，且允许改变类型
let title = "Snow Halo";
let title = title.len(); // 现在是 usize
println!("{}", title);

// 常量必须标注类型，命名全大写下划线分隔
const MAX_PLAYLIST: usize = 100;
println!("{}", MAX_PLAYLIST);

// 一次绑定多个值：P主与其合作歌姬
let (producer, singer) = ("MikuP", "Miku");
println!("{} feat. {}", producer, singer);

// 下划线开头表示有意不使用，不触发警告
let _draft_lyric = "未完成的歌词";
println!("草稿已保存");

// 有符号 i8/i16/i32/i64/i128/isize，无符号 u 系列
let like_count: u64 = 86_120; // 累计点赞
let rank: i32 = -3;           // 榜单升降
println!("{} {}", like_count, rank);

// f32 单精度、f64 双精度，默认推断为 f64
let rating: f64 = 4.9;  // 歌曲评分
let volume: f32 = 0.85; // 音量增益
println!("{} {}", rating, volume);

// bool 只有 true 与 false 两种取值
let is_live = true;        // 是否正在直播
let is_vip: bool = false;  // 是否为会员
println!("{} {}", is_live, is_vip);

// char 为 4 字节 Unicode 标量值，单引号包裹
let grade = 'S';  // 歌曲评级
let word = '中';  // 任意 Unicode 字符均合法
println!("{} {}", grade, word);

// 元组可混合类型，用 .0 .1 按位置访问
let song = ("Snow Halo", 246, 4.9); // 名/秒数/评分
println!("{} {}s {}分", song.0, song.1, song.2);

// 数组长度编译期固定，类型为 [T; N]
let rgb: [u8; 3] = [255, 102, 204]; // 应援色
println!("R={} 长度={}", rgb[0], rgb.len());

// &str 指向一段只读 UTF-8 文本，字面量默认是 &str
let lyric: &str = "星屑与雨声";
let title = "Snow Halo";
println!("{} / {}", title, lyric);

// Option<T> 只有 Some(v) 与 None 两种可能
let chart_rank: Option<u32> = Some(7); // 在榜第 7
let removed: Option<u32> = None;       // 已下榜
println!("{:?} {:?}", chart_rank, removed);

// as 完成基础数值类型转换
let total_seconds: u32 = 246;
let minutes = total_seconds / 60;             // 整数除法
let precise = total_seconds as f64 / 60.0;    // 转浮点再除
println!("{} {}", minutes, precise);

// 条件不加括号，块必须用花括号包裹
let requests = 128;
if requests > 100 {
    println!("开启应援通道");
} else {
    println!("请排队等待");
}

// if 是表达式，两个分支必须返回同类型
let fans = 500;
let badge = if fans >= 1000 { "金徽章" } else { "银徽章" };
println!("{}", badge);

// loop 无限循环，break 可携带返回值
let mut count = 0;
let result = loop {
    count += 1;
    if count == 3 { break count * 10; }
};
println!("{}", result);

// while 先判断条件，再决定是否继续执行
let mut tickets = 3;
while tickets > 0 {
    tickets -= 1; // 逐张放票
}
println!("{}", tickets);

// a..b 左闭右开，a..=b 包含末端
for day in 1..=3 {
    println!("巡演第 {} 天", day);
}

// iter_mut() 提供可变借用，可原地修改元素
let mut votes = [9, 8, 10];
for v in votes.iter_mut() {
    *v += 1; // 全员加一票
}
println!("{:?}", votes);

// match 必须穷尽所有可能，_ 为通配分支
let code = 2;
let status = match code {
    1 => "预订中",
    2 => "售票中",
    _ => "已结束",
};
println!("{}", status);

// fn 定义函数，参数必须显式标注类型
fn sign_song(producer: &str, singer: &str) {
    println!("{} 为 {} 写歌", producer, singer);
}

fn main() {
    sign_song("MikuP", "Miku");
}

// 最后一个表达式不带分号，即为返回值
fn rating_bonus(rating: f64) -> f64 {
    if rating > 4.5 { 10.0 } else { 0.0 }
}

fn main() {
    println!("{}", rating_bonus(4.9));
}

// String 等堆类型赋值时移动所有权，而非复制
fn archive(title: String) {
    println!("已归档：{}", title);
}

let song = String::from("Snow Halo");
archive(song); // 所有权移入函数

// 所有权移动后，原变量即失效不可再用
let song = String::from("Snow Halo");
let picked = song; // 所有权移动到 picked
println!("{}", song); // 编译错误：borrow of moved value
println!("{}", picked);

// clone 复制堆上数据，原变量保持可用
let song = String::from("Snow Halo");
let backup = song.clone();
println!("{} / {}", song, backup);

// 整数、浮点、bool、char 等实现 Copy，赋值即复制
let plays = 1024;
let stat = plays; // 复制而非移动
println!("{} {}", plays, stat);

// 返回值把所有权从函数内部移出到调用方
fn make_title() -> String {
    String::from("Snow Halo")
}

let title = make_title(); // title 获得所有权
println!("{}", title);

// & 借用值而不取得所有权，函数调用后原值仍可用
fn count_words(lyric: &str) -> usize {
    lyric.split_whitespace().count()
}

let lyric = String::from("星屑 雨声 舞台");
println!("{}", count_words(&lyric));

// &mut 可修改数据，原变量必须声明为 mut
fn add_like(count: &mut u32) {
    *count += 1; // 解引用后自增
}

let mut likes = 10;
add_like(&mut likes);

// 同时存在多个不可变引用是允许的
let song = String::from("Snow Halo");
let r1 = &song;
let r2 = &song;
println!("{} / {}", r1, r2);

// 已有可变借用时，不能再创建任何其他借用
let mut song = String::from("Snow Halo");
let editing = &mut song;
let reading = &song; // 编译错误：同时可变与不可变借用
println!("{} {}", editing, reading);

// 通过解引用直接修改原数据
let mut votes = 9;
let r = &mut votes;
*r += 1; // votes 变为 10
println!("{}", votes);

// 切片借用字符串的一段连续内容
let lyric = String::from("Snow Halo");
let first_word = &lyric[0..4]; // "Snow"
println!("{}", first_word);

// 切片同样适用于数组与 Vec，..3 表示从头到下标 2
let tops = [1, 2, 3, 4, 5];
let top3 = &tops[..3]; // 前三名
println!("{:?}", top3);

// struct 定义命名字段结构体，字段类型逐一标注
struct Vsinger {
    name: String,
    theme_color: String, // 应援色
    fans: u64,
}

// 字段名: 值 初始化；实例声明为 mut 则整体可变
let mut miku = Vsinger {
    name: String::from("Miku"),
    theme_color: String::from("#39C5BB"),
    fans: 1_000_000,
};
miku.fans += 1;

// 显式给出新值字段，其余从 miku 复制（miku 为已有实例）
let luka = Vsinger {
    name: String::from("Luka"),
    theme_color: String::from("#FFAACF"),
    ..miku
};

// 字段无名，按 .0 .1 位置访问
struct Ticket(u32, String); // 座位号, 看台区域

let seat = Ticket(7, String::from("A 区"));
println!("{} 区 {} 号", seat.1, seat.0);

// &self 只读借用自身；方法用实例.方法() 调用
struct Concert { city: String, tickets: u32 }

impl Concert {
    fn sold_out(&self) -> bool {
        self.tickets == 0
    }
}

// enum 列出某事物的全部可能状态
enum SongStatus {
    Draft,     // 未发布
    Published, // 已上线
    Archived,  // 已下架
}

// 各变体可携带数量与类型不同的数据
enum Reward {
    Coin(u64),      // 应援币
    Ticket(String), // 演唱会门票
    Nothing,        // 谢谢参与
}

// match 按变体分支，并解构出携带的数据
let gift = Reward::Coin(520);
let msg = match gift {
    Reward::Coin(n) => format!("获得 {} 应援币", n),
    Reward::Ticket(area) => format!("{} 门票", area),
    Reward::Nothing => String::from("下次努力"),
};

// Vec 是可增长向量，push 在尾部追加
let mut playlist: Vec<&str> = vec!["Snow Halo", "Starlight"];
playlist.push("Aurora");
println!("{:?}", playlist);

// 索引越界会 panic；get 返回 Option 更安全
let playlist = vec!["Snow Halo", "Aurora"];
let first = &playlist[0];     // 直接索引
let maybe = playlist.get(5);  // 越界得到 None
println!("{:?} {:?}", first, maybe);

// &mut 遍历获得可变借用，解引用后修改
let mut scores = vec![88, 92, 79];
for s in &mut scores {
    *s += 1;
}
println!("{:?}", scores);

// pop 移除并返回尾部元素，类型为 Option
let mut queue = vec!["encore", "finale"];
let last = queue.pop(); // Some("finale")
println!("{:?} {:?}", queue, last);

// String 是堆上可增长字符串，与 &str 不同
let mut title = String::from("Snow");
title.push_str(" Halo"); // 追加字符串片段
title.push('!');         // 追加单个字符

// + 会拿走左操作数的所有权；format! 更灵活
let p = String::from("Miku");
let tag = p + " feat. Luka";
let full = format!("{} (Live)", tag);

// HashMap 存储键值对，使用前需引入标准库模块
use std::collections::HashMap;

let mut votes = HashMap::new();
votes.insert("Miku", 1024);
votes.insert("Luka", 860);

// get 返回 Option<&V>，键不存在时得到 None
use std::collections::HashMap;

let votes = HashMap::from([("Miku", 1024)]);
if let Some(v) = votes.get("Miku") {
    println!("Miku：{} 票", v);
}

// entry 不存在时插入默认值，常用于计数统计
use std::collections::HashMap;

let mut counter = HashMap::new();
for song in ["Snow", "Snow", "Aurora"] {
    *counter.entry(song).or_insert(0) += 1;
}

// 不可恢复错误用 panic!，立即终止当前线程
fn check_seat(seat: i32) {
    if seat < 0 {
        panic!("座位号不能为负：{}", seat);
    }
}

// Ok(T) 表示成功，Err(E) 表示失败，交由调用方处理
fn check_sold_out(left: u32) -> Result<(), String> {
    if left == 0 { Err(String::from("门票已售罄")) } else { Ok(()) }
}

// match 强制处理成功与失败，不留遗漏
match check_sold_out(0) {
    Ok(()) => println!("购票成功"),
    Err(msg) => println!("失败：{}", msg),
}

// unwrap 失败即 panic；expect 可自定义报错信息
let input = "520";
let count = input.parse::<u32>().expect("票数必须是数字");
println!("售出 {} 张", count);

// ? 遇 Err 立即把错误返回给调用方，成功则取出值
fn buy_ticket(left: u32) -> Result<u32, String> {
    check_sold_out(left)?;
    Ok(left - 1)
}

// main 可返回 Result，错误最终打印给用户
fn main() -> Result<(), Box<dyn std::error::Error>> {
    let n: u32 = "128".parse()?; // 解析失败自动返回
    println!("售出 {} 张", n);
    Ok(())
}

// 用枚举表达业务错误，配合 match 精确处理
#[derive(Debug)]
enum TicketError {
    SoldOut,          // 已售罄
    InvalidSeat(i32), // 非法座位号
}

// T 是类型参数，PartialOrd 约束其支持比较
fn loudest<T: PartialOrd>(a: T, b: T) -> T {
    if a > b { a } else { b }
}

fn main() {
    println!("{}", loudest(88, 92));
}

// 同一结构体可服务多种元素类型
struct Playlist<T> {
    owner: String, // 播放单创建者
    items: Vec<T>, // 条目集合
}

// 只有签名的的方法必须实现；带默认体可省略
trait Perform {
    fn stage_name(&self) -> String;
    fn greet(&self) -> String { // 默认实现
        format!("大家好，我是 {}", self.stage_name())
    }
}

// 为具体类型补齐 trait 要求的全部必需方法
struct Vsinger { name: String }

impl Perform for Vsinger {
    fn stage_name(&self) -> String {
        self.name.clone()
    }
}

// T: Perform 限定参数必须实现该行为
fn open_show<T: Perform>(artist: &T) {
    println!("{}", artist.greet());
}

// 与泛型约束等价的简写形式，适合单参数场景
fn encore(artist: &impl Perform) -> String {
    artist.greet()
}

// 'a 声明多个引用的存活约束，保证返回值引用有效
fn longer<'a>(a: &'a str, b: &'a str) -> &'a str {
    if a.len() > b.len() { a } else { b }
}

let title = longer("Snow Halo", "Aurora");

// 结构体借用外部数据时，必须声明生命周期
struct Highlight<'a> {
    text: &'a str, // 借用的歌词片段
}

let lyric = String::from("stardust rain");
let h = Highlight { text: &lyric[0..8] }; // "stardust"

// 参数类型通常可自动推断，调用与函数相同
let add_fans = |base: u64, delta: u64| base + delta;
let double = |n| n * 2;
println!("{} {}", add_fans(1000, 5), double(8));

// 闭包定义处捕获外部变量，默认为不可变借用
let theme = String::from("#39C5BB");
let show = || println!("应援色：{}", theme);
show();

// move 强制转移所有权，常用于线程或延长生命周期
let owner = String::from("MikuP");
let stamp = move || println!("出品：{}", owner);
stamp();

// iter() 逐个产出元素的只读引用
let songs = vec!["Snow Halo", "Aurora"];
for name in songs.iter() {
    println!("{}", name);
}

// map 是惰性适配器，collect 触发执行并收集
let lengths: Vec<usize> = vec!["Snow", "Aurora"]
    .iter()
    .map(|s| s.len())
    .collect();
println!("{:?}", lengths);

// filter 只保留闭包返回 true 的元素
let votes = vec![920, 1024, 860];
let hot: Vec<i32> = votes.into_iter().filter(|v| *v > 900).collect();
println!("{:?}", hot);

// 适配器惰性组合，sum 等消费方法触发计算
let total: u32 = vec![88, 92, 79]
    .into_iter()
    .filter(|v| *v >= 85)
    .map(|v| v + 1)
    .sum();

// enumerate 产出 (下标, 元素) 二元组
let names = vec!["Miku", "Luka"];
for (i, name) in names.iter().enumerate() {
    println!("{} 号：{}", i + 1, name);
}
